import{_ as e,o as t,c as a,ag as s}from"./chunks/framework.D9ghT4bC.js";const l="/Unciv/assets/1778417407140.BQp-ABK7.png",r="/Unciv/assets/1778417421124.BggyvfvK.png",o="/Unciv/assets/1778417482159.BAeDu30I.png",n="/Unciv/assets/1778417521851.BmBobuVW.png",p="/Unciv/assets/1778417769315.4Z0fVW0T.png",c="/Unciv/assets/1778417725003.BptUUT3j.png",f=JSON.parse('{"title":"Emperors and Deities 模组介绍","description":"","frontmatter":{"title":"Emperors and Deities 模组介绍"},"headers":[],"relativePath":"zh/Community/Mods/Emperors-and-Deities/index.md","filePath":"zh/Community/Mods/Emperors-and-Deities/index.md"}'),d={name:"zh/Community/Mods/Emperors-and-Deities/index.md"};function m(h,i,u,g,_,b){return t(),a("div",null,[...i[0]||(i[0]=[s('<h2 id="关于-end" tabindex="-1">关于 EnD <a class="header-anchor" href="#关于-end" aria-label="Permalink to &quot;关于 EnD&quot;">​</a></h2><p>Emperors and Deities（帝王和神明）既没有帝王，也没有神明，而是一个颠覆Unciv/文明5玩法的大规模重置规则集mod。 包含有：</p><ul><li><p><strong>多样的局内路线抉择</strong>：政策，宗教，历史政体，事件。可以说是借鉴了文明7和人类的部分机制，但是使用个人理解重新架构。开局选择区域，之后这片多姿多彩的土地上的所有民族和文明都归你指挥。（中世纪以后内容施工中）</p><p><img src="'+l+'" alt="1778417407140"></p><p><img src="'+r+'" alt="1778417421124"></p></li><li><p><strong>单位和建筑机制全盘细化</strong>：单位和建筑不单单数量大幅度提升，甚至还有细化分类和Tag支持，和局内路线息息相关。是选择把军权交给与国同休的军事贵族还是贯彻职业化军队的改革？</p><p><img src="'+o+'" alt="1778417482159"></p></li><li><p><strong>科技树全盘细化</strong>：从新石器时代的起始科技到帝国时代的线列步兵，从工业时代的电报到信息时代的数据中心。EnD的科技树包含了很多原版没有概括的领域，包括造纸术，水泥，定装弹等。<s>而且基本上每个科技都个大汁水多</s>。(目前电气-未来时代暂时还在施工。)</p><p><img src="'+n+'" alt="1778417521851"></p></li><li><p><strong>快乐机制重置</strong>：支撑黄金时代的帝国龙骨不再是区区奢侈品资源，而是它们带来的暴利。奢侈品资源不再直接提供快乐，而崭新的市政建筑树，医疗建筑树，和其他基础设施将会决定城市治理的难度。完全同化城市现在也需要大量准备。</p></li><li><p>全新稳定度机制：不快乐会爆负面事件影响你的稳定度，之后叛军减成两开花。只有把你积攒的影响力花掉，你才能逆转乾坤。当然，建立健全的市政才是治本之举。</p><p><img src="'+p+'" alt="1778417769315"></p></li><li><p>更多小巧思：把一个城市产出的多余人口/资源放到另外一个城市？完全可以！让商朝打败周朝，让哈拉帕人击败雅利安人？取决于你的意志。即使白板文明，也可以通过局内成长享受大部分游戏内容。</p><p><img src="'+c+'" alt="1778417725003"></p></li></ul><h3 id="核心理念" tabindex="-1">核心理念 <a class="header-anchor" href="#核心理念" aria-label="Permalink to &quot;核心理念&quot;">​</a></h3><blockquote><p>&quot;能改的全部动了。&quot; - CX61</p></blockquote><p>本模组忠实于历史准确度。但是这个定义并不是完全准守历史做无止境细化，而是筛选适合文明这个六边形棋盘的要素，进行阐释和精炼。争取让玩家体验到《文明》系列玩法的船新一面。</p><h3 id="快速链接" tabindex="-1">快速链接 <a class="header-anchor" href="#快速链接" aria-label="Permalink to &quot;快速链接&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">模组资源</p><ul><li><a href="https://github.com/chenxing61/Emperors-and-Deities" target="_blank" rel="noreferrer">GitHub 仓库</a></li></ul></div><h3 id="加入社区-特急" tabindex="-1">加入社区（特急） <a class="header-anchor" href="#加入社区-特急" aria-label="Permalink to &quot;加入社区（特急）&quot;">​</a></h3><p>如果您对模组有任何建议或问题，欢迎加入我们的 QQ 群：</p><p><a href="https://qm.qq.com/q/FutBLHn2M4" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/QQ%E7%BE%A4-%E7%82%B9%E5%87%BB%E5%8A%A0%E5%85%A5-green?logo=tencent-qq" alt="QQ 群"></a></p><p>或者Discord群组：</p><p><a href="https://discord.gg/EYG6hT3W7N" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/1415865496758259744?label=Discord&amp;color=blue" alt="Discord"></a></p><h3 id="总之请试玩该模组-因为没人玩既调不了平衡-也做不了qol" tabindex="-1">总之请试玩该模组！因为没人玩既调不了平衡，也做不了QoL！！！ <a class="header-anchor" href="#总之请试玩该模组-因为没人玩既调不了平衡-也做不了qol" aria-label="Permalink to &quot;总之请试玩该模组！因为没人玩既调不了平衡，也做不了QoL！！！&quot;">​</a></h3><h3 id="安装指南" tabindex="-1">安装指南 <a class="header-anchor" href="#安装指南" aria-label="Permalink to &quot;安装指南&quot;">​</a></h3><ol><li>下载最新版模组文件</li><li>将模组文件夹放入游戏 <code>mods/</code> 目录</li><li>在游戏设置中启用 Emperors and Deities</li><li>开始新游戏即可体验</li><li>或者，如果你有github通行方式，可以直接在游戏内下载。</li></ol><div class="warning custom-block"><p class="custom-block-title">注意</p><ul><li>模组仅支持新游戏，无法兼容已有存档</li><li>建议在标准速度下游玩以获得最佳体验</li></ul></div><h3 id="致谢" tabindex="-1">致谢 <a class="header-anchor" href="#致谢" aria-label="Permalink to &quot;致谢&quot;">​</a></h3><p>感谢所有为模组做出贡献的玩家和开发者！</p><p>特别感谢：</p><ul><li>Unciv 开发团队提供的优秀游戏平台（Yarim和其他牢开发者们）</li><li>所有已经参与测试和反馈的玩家</li><li>Unciv 社区的支持（模组大佬们）</li><li>提供翻译的社区成员</li><li>Bucketeer提供的美术支援</li><li>还有看到这里的你！</li></ul>',21)])])}const E=e(d,[["render",m]]);export{f as __pageData,E as default};
